return ['domain'=>'acfml','plural-forms'=>'nplurals=2; plural=(n > 1);','language'=>'fr_FR','project-id-version'=>'Advanced Custom Fields Multilingual 5.2.0','pot-creation-date'=>'2026-10-20 11:28+0000','po-revision-date'=>'2026-10-20 11:28+0000','x-generator'=>'PTC (Private Translation Cloud)','messages'=>['Advanced Custom Fields Multilingual'=>'Advanced Custom Fields Multilingual','https://wpml.org/documentation/wpml-core-and-add-on-plugins/acfml/'=>'https://wpml.org/documentation/wpml-core-and-add-on-plugins/acfml/','Adds compatibility between WPML and Advanced Custom Fields | <a href="https://wpml.org/documentation/translating-your-contents/acf/?utm_source=plugin&utm_medium=gui&utm_campaign=acfml">Documentation</a>'=>'Ajoute une compatibilité entre WPML et Advanced Custom Fields | <a href="https://wpml.org/documentation/translating-your-contents/acf/?utm_source=plugin&utm_medium=gui&utm_campaign=acfml">Documentation</a>','OnTheGoSystems'=>'OnTheGoSystems','http://www.onthegosystems.com/'=>'http://www.onthegosystems.com/','Displayed when editing an ACF field in a translation, showing its value in the original language; %1$s and %2$s turn the string into bold, and %3$s is the actual original value.%1$sOriginal%2$s: %3$s'=>'%1$sOriginal%2$s : %3$s','This type of ACF field will always be set to "Copy once".'=>'Ce type de champ ACF sera toujours réglé sur « Copier une seule fois ».','ACF field name:'=>'Nom du champ ACF :','ACF field type:'=>'Type de champ ACF :','Translation preferences'=>'Préférences de traduction','What to do with field\'s value when post/page is going to be translated'=>'Que faire de la valeur du champ lorsque la publication/page va être traduite','Translate (your current setting, no longer offered for this field type)'=>'Traduire (votre réglage actuel, n’est plus proposé pour ce type de champ)','Kept because it is your current setting. This value is no longer offered for this field type.'=>'Conservé car il s’agit de votre réglage actuel. Cette valeur n’est plus proposée pour ce type de champ.','Not recommended for this field type.'=>'Non recommandé pour ce type de champ.','Translated pages start without this content.'=>'Les pages traduites commencent sans ce contenu.','Editable in other languages, and starts empty.'=>'Modifiable dans d’autres langues, et commence vide.','Visitors in every language always see exactly what the original shows.'=>'Les visiteurs de chaque langue voient toujours exactement ce que l’original affiche.','Shown locked in other languages, so it cannot be edited there.'=>'Affiché comme verrouillé dans les autres langues, il ne peut donc pas y être modifié.','Starts the same as the original, then each language goes its own way.'=>'Commence de la même manière que l’original, puis chaque langue suit son propre chemin.','Editable in every language, and permanently yours to maintain by hand.'=>'Modifiable dans chaque langue, et reste à votre charge pour une maintenance manuelle.','Visitors see this in their own language.'=>'Les visiteurs voient ceci dans leur propre langue.','Filled by the translation and edited in the translation editor.'=>'Rempli par la traduction et modifié dans l’éditeur de traduction.','Edit the field to set the translation preference.'=>'Modifiez le champ pour définir la préférence de traduction.','ACFML is updating translation preferences for strings in Gutenberg Blocks. Keep using your site as usual. This notice will disappear when the process is done.'=>'ACFML met à jour les préférences de traduction pour les chaînes dans les blocs Gutenberg. Continuez à utiliser votre site comme d’habitude. Cet avis disparaîtra une fois le processus terminé.','ACFML is enabled but not effective. It requires WPML in order to work.'=>'ACFML est activé mais n’est pas effectif. Il nécessite WPML pour fonctionner.','ACFML is enabled but not effective. It requires Advanced Custom Fields or ACF PRO in order to work.'=>'ACFML est activé mais inopérant. Il nécessite Advanced Custom Fields ou ACF PRO pour fonctionner.','Activate Advanced Custom Fields'=>'Activer Advanced Custom Fields','Install Advanced Custom Fields'=>'Installer Advanced Custom Fields','Field groups are set to "Translatable" in WPML settings, which prevents ACF fields from being translated.'=>'Les groupes de champs sont réglés sur « Traduisible » dans les paramètres de WPML, ce qui empêche la traduction des champs ACF.','This is almost never intended.'=>'Ceci n’est presque jamais intentionnel.','A configuration file (wpml-config.xml) controls this setting on this site, so it cannot be changed from here. Edit that file, or ask whoever maintains it to set the ACF field group post type to Not translatable.'=>'Un fichier de configuration (wpml-config.xml) contrôle ce réglage sur ce site, il ne peut donc pas être modifié d’ici. Modifiez ce fichier ou demandez à la personne qui le gère de régler le type de publication du groupe de champs ACF sur « Ne pas traduire ».','Field group copies already created in other languages stay on the site. Changing this setting does not delete them.'=>'Les copies de groupes de champs déjà créées dans d’autres langues restent sur le site. La modification de ce réglage ne les supprime pas.','Set field groups to Not translatable'=>'Régler les groupes de champs sur « Ne pas traduire »','Why this matters'=>'Pourquoi est-ce important ?','If any field is set to "Translatable", WPML will re-translate the %d posts using this field group.'=>'Si un champ est réglé sur « Traduire », WPML retraduira les %d publications utilisant ce groupe de champs.','Some posts using this field group have translations. Once you change the translation option, WPML needs to update the translation status of the posts. This can take up to 1 minute.'=>'Certaines publications utilisant ce groupe de champs ont des traductions. Une fois que vous aurez modifié l’option de traduction, WPML devra mettre à jour le statut de traduction des publications. Cela peut prendre jusqu’à 1 minute.','Some posts using this field group have translations. Once you change the translation option, WPML needs to update the translation status of the posts. This can take up to %d hours.'=>'Certaines publications utilisant ce groupe de champs ont des traductions. Une fois que vous aurez modifié l’option de traduction, WPML devra mettre à jour le statut de traduction des publications. Cela peut prendre jusqu’à %d heures.','Some posts using this field group have translations. Once you change the translation option, WPML needs to update the translation status of the posts. This can take up to %d minutes.'=>'Certaines publications utilisant ce groupe de champs ont des traductions. Une fois que vous aurez modifié l’option de traduction, WPML devra mettre à jour le statut de traduction des publications. Cela peut prendre jusqu’à %d minutes.','Locked by WPML so that ACF fields stay translatable. Click here to unlock and change it anyway.'=>'Verrouillé par WPML pour que les champs ACF restent traduisibles. Cliquez ici pour déverrouiller et modifier quand même.','Set translation preferences for the attached taxonomy'=>'Définir les préférences de traduction pour la taxonomie jointe','Set translation preferences for the attached post type'=>'Définir les préférences de traduction pour le type de publication joint','If you want to translate your fields, go to the WPML Settings page and make the taxonomy attached to this field group translatable. '=>'Si vous souhaitez traduire vos champs, allez sur la page des paramètres de WPML et rendez traduisible la taxonomie jointe à ce groupe de champs. ','If you want to translate your fields, go to the WPML Settings page and %1$smake the post type attached to this field group translatable%2$s.'=>'Si vous souhaitez traduire vos champs, allez sur la page des paramètres de WPML et %1$srendez traduisible le type de publication joint à ce groupe de champs%2$s.','Expert'=>'Expert','Same content in every language, translated'=>'Même contenu dans chaque langue, traduit','Each language has its own content'=>'Chaque langue a son propre contenu','Translate is not offered on container fields, because it replaces the value your theme reads. The fields inside carry their own preferences.'=>'L’option « Traduire » n’est pas proposée pour les champs conteneurs, car elle remplace la valeur lue par votre thème. Les champs à l’intérieur portent leurs propres préférences.','Translate lets each language point at its own address, which an external link often needs. A link to a page on this site already points at that page in the reader\'s language, so leave it as it is.'=>'« Traduire » permet à chaque langue de pointer vers sa propre adresse, ce dont un lien externe a souvent besoin. Un lien vers une page de ce site pointe déjà vers cette page dans la langue du lecteur, laissez-le donc tel quel.','Translate sends the link text and the URL. The target keeps the value you set, and a URL you leave as it is points at the page in the reader\'s language.'=>'« Traduire » envoie le texte du lien et l\'URL. La cible conserve la valeur que vous avez définie, et une URL que vous laissez telle quelle pointe vers la page dans la langue du lecteur.','Translating an address produces one that does not exist. An e-mail address is the same in every language.'=>'Traduire une adresse produit une adresse qui n’existe pas. Une adresse e-mail est la même dans toutes les langues.','A color code is not language content. Translating it changes the color your visitors see.'=>'Un code couleur n’est pas un contenu linguistique. Le traduire modifie la couleur que voient vos visiteurs.','The stored value is a fixed date format that your theme reads. Translating it breaks the format.'=>'La valeur stockée est un format de date fixe lu par votre thème. La traduire casse le format.','The stored value is the choice key, not the label your visitors see. Translating it stops the key from matching your choices. Translate the labels in <b>String Translation</b> instead.'=>'La valeur stockée est la clé du choix, pas le libellé que voient vos visiteurs. La traduire empêche la clé de correspondre à vos choix. Traduisez plutôt les libellés dans la <b>Traduction de chaînes</b>.','This value is read by your theme or plugin code. A translated value can stop matching what the code expects.'=>'Cette valeur est lue par le code de votre thème ou de votre extension. Une valeur traduite peut ne plus correspondre à ce que le code attend.','The file decides this again on every import, so changes made elsewhere do not stick.'=>'Le fichier en décide à nouveau lors de chaque importation, les modifications effectuées ailleurs ne sont donc pas conservées.','Edit %s, or remove the entry there, to manage this field on this screen.'=>'Modifiez %s, ou supprimez l’entrée correspondante, pour gérer ce champ sur cet écran.','Edit the configuration file, or remove the entry there, to manage this field on this screen.'=>'Modifiez le fichier de configuration, ou supprimez l’entrée correspondante, pour gérer ce champ sur cet écran.','That is not the value selected above. Saving this field group applies the value above.'=>'Ce n’est pas la valeur sélectionnée ci-dessus. L’enregistrement de ce groupe de champs applique la valeur ci-dessus.','This field group is also in %s. That file re-applies these settings the next time the group is synced.'=>'Ce groupe de champs se trouve également dans %s. Ce fichier réappliquera ces réglages lors de la prochaine synchronisation du groupe.','Locked. Managed by your theme, in its wpml-config.xml file.'=>'Verrouillé. Géré par votre thème, dans son fichier wpml-config.xml.','Locked. Managed by a plugin, in its wpml-config.xml file.'=>'Verrouillé. Géré par une extension, dans son fichier wpml-config.xml.','Locked. Managed by a configuration file WPML downloaded for one of your plugins or themes.'=>'Verrouillé. Géré par un fichier de configuration que WPML a téléchargé pour l’une de vos extensions ou l’un de vos thèmes.','Locked. Managed by the custom XML configuration saved in WPML settings.'=>'Verrouillé. Géré par la configuration XML personnalisée enregistrée dans les paramètres de WPML.','Locked. Managed by a configuration file on this site.'=>'Verrouillé. Géré par un fichier de configuration sur ce site.','Set in the field group "%s", which uses the same field name.'=>'Défini dans le groupe de champs « %s », qui utilise le même nom de champ.','Set in the field group\'s local JSON file.'=>'Défini dans le fichier JSON local du groupe de champs.','Set in the field group\'s local JSON file, %s.'=>'Défini dans le fichier JSON local du groupe de champs, %s.','Registered with PHP by your theme or a plugin.'=>'Enregistré avec PHP par votre thème ou une extension.','Set on the WPML Settings screen (Custom Fields Translation).'=>'Défini sur l’écran des paramètres de WPML (Traduction des champs personnalisés).','Set here, on this screen.'=>'Défini ici, sur cet écran.','Right now this field is translated, so visitors see it in their own language.'=>'Actuellement, ce champ est traduit, les visiteurs le voient donc dans leur propre langue.','Right now this field stays identical in every language.'=>'Actuellement, ce champ reste identique dans chaque langue.','Right now this field starts as a copy in every language, then each language keeps its own.'=>'Actuellement, ce champ commence par une copie dans chaque langue, puis chaque langue conserve la sienne.','Right now this field stays out of translations.'=>'Actuellement, ce champ reste en dehors des traductions.','Don\'t translate'=>'Ne pas traduire','Copy'=>'Copier','Copy once'=>'Copier une seule fois','Translate'=>'Traduire','Field groups'=>'Groupes de champs','Fields'=>'Champs','Posts'=>'Publications','Review them one by one'=>'Les examiner un par un','Apply the recommended setup to %d group'=>'Appliquer la configuration recommandée à %d groupe' . "\0" . 'Appliquer la configuration recommandée aux %d','%d ACF field group is not configured for translation.'=>'%d groupe de champs ACF n’est pas configuré pour la traduction.' . "\0" . '%d groupes de champs ACF ne sont pas configurés pour la traduction.','%d post'=>'%d publication' . "\0" . '%d publications','%1$s field, used on %2$s, would be skipped and stay in %3$s.'=>'%1$s champ, utilisé sur %2$s, serait ignoré et resterait en %3$s.' . "\0" . '%1$s champs, utilisés sur %2$s, seraient ignorés et resteraient en %3$s.','%1$s field, used on %2$s, would be skipped and stay untranslated.'=>'%1$s champ, utilisé sur %2$s, serait ignoré et resterait non traduit.' . "\0" . '%1$s champs, utilisés sur %2$s, seraient ignorés et resteraient non traduits.','You are not allowed to change the translation setup of ACF field groups.'=>'Vous n’êtes pas autorisé à modifier la configuration de traduction des groupes de champs ACF.','You are not allowed to change the WPML translation settings on this site.'=>'Vous n’êtes pas autorisé à modifier les paramètres de traduction de WPML sur ce site.','To change the translation options for custom fields, edit the field group "%s".'=>'Pour modifier les options de traduction des champs personnalisés, modifiez le groupe de champs « %s ».','These fields come from ACF’s Local JSON files. To change their translation options, go to ACF → Field Groups, sync them, and then edit their settings.'=>'Ces champs proviennent des fichiers JSON locaux d’ACF. Pour modifier leurs options de traduction, allez dans ACF → Groupes de champs, synchronisez-les, puis modifiez leurs réglages.','This field and its translation setting are registered via PHP by your theme or plugin. Changes made here will override the original configuration.'=>'Ce champ et son réglage de traduction sont enregistrés via PHP par votre thème ou extension. Les modifications effectuées ici remplaceront la configuration d’origine.','ACF translation setup'=>'Configuration de la traduction ACF','Translation setup'=>'Configuration de la traduction','You are not allowed to review the translation setup of ACF field groups.'=>'Vous n’êtes pas autorisé à examiner la configuration de traduction des groupes de champs ACF.','Field group'=>'Groupe de champs','Setup'=>'Configuration','Actions'=>'Actions','This site has no ACF field groups yet.'=>'Ce site n’a pas encore de groupes de champs ACF.','Alert:'=>'Alerte :','How to do that'=>'Comment faire cela','View fields'=>'Afficher les champs','Open Dashboard'=>'Ouvrir le tableau de bord','Apply the recommended setup'=>'Appliquer la configuration recommandée','Every field group stored in this site’s database already has a translation setup.'=>'Chaque groupe de champs stocké dans la base de données de ce site possède déjà une configuration de traduction.','Back to the field groups'=>'Retour aux groupes de champs','Every field in those groups then gets the translation preference WPML recommends for its field type. A preference that was set by hand in one of them is replaced.'=>'Chaque champ de ces groupes reçoit alors la préférence de traduction que WPML recommande pour son type de champ. Une préférence qui a été définie manuellement dans l’un d’eux est remplacée.','Field groups that come from your theme, a plugin’s code, or an acf-json file are not changed. They cannot be saved from here.'=>'Les groupes de champs provenant de votre thème, du code d’une extension ou d’un fichier acf-json ne sont pas modifiés. Ils ne peuvent pas être enregistrés d’ici.','Cancel'=>'Annuler','%d field group.'=>'%d groupe de champs.' . "\0" . '%d groupes de champs.','All of them have a translation setup.'=>'Tous possèdent une configuration de traduction.','%d is not configured.'=>'%d n’est pas configuré.' . "\0" . '%d ne sont pas configurés.','Apply recommended setup to the %d unconfigured group'=>'Appliquer la configuration recommandée au %d groupe non configuré' . "\0" . 'Appliquer la configuration recommandée aux %d groupes non configurés','This sets %1$d field group to “%2$s”.'=>'Ceci règle %1$d groupe de champs sur « %2$s ».' . "\0" . 'Ceci règle %1$d groupes de champs sur « %2$s ».','%d field group is defined in code, so it cannot be configured from here.'=>'%d groupe de champs est défini dans le code, il ne peut donc pas être configuré d’ici.' . "\0" . '%d groupes de champs sont définis dans le code, ils ne peuvent donc pas être configurés d’ici.','Not configured'=>'Non configuré','Not configured (defined in code)'=>'Non configuré (défini dans le code)','Set for each field (defined in code)'=>'Défini pour chaque champ (défini dans le code)','Set for each field in WPML Settings (defined in code)'=>'Défini pour chaque champ dans les réglages de WPML (défini dans le code)','%d field set manually'=>'%d champ défini manuellement' . "\0" . '%d champs définis manuellement','Nothing decides how these fields are translated. Set %s on the fields in the code that registers this group.'=>'Rien ne décide de la manière dont ces champs sont traduits. Définissez %s sur les champs dans le code qui enregistre ce groupe.','from an acf-json file'=>'depuis un fichier acf-json','from an acf-json file that is newer than this site’s copy'=>'depuis un fichier acf-json plus récent que la copie de ce site','from your theme or a plugin’s code'=>'depuis votre thème ou le code d’une extension','%d field group now uses the recommended setup.'=>'%d groupe de champs utilise désormais la configuration recommandée.' . "\0" . '%d groupes de champs utilisent désormais la configuration recommandée.','%d field group has a newer acf-json file waiting to be synced, so that file decides its setup.'=>'%d groupe de champs a un fichier acf-json plus récent en attente de synchronisation, c’est donc ce fichier qui décide de sa configuration.' . "\0" . '%d groupes de champs ont un fichier acf-json plus récent en attente de synchronisation, ce sont donc ces fichiers qui décident de leur configuration.','Translation Option'=>'Option de traduction','Multilingual Setup'=>'Configuration multilingue','Loading...'=>'Chargement...','Activate <b>String Translation</b>'=>'Activer la <b>Traduction de chaînes</b>','To translate field group names and labels, please %1$sinstall and activate WPML’s String Translation add-on%2$s.'=>'Pour traduire les noms et les libellés des groupes de champs, veuillez %1$sinstaller et activer le module de traduction de chaînes de WPML%2$s.','Activate now'=>'Activer maintenant','Go back'=>'Retour','Set Up <b>Field Group Translation</b>'=>'Configurer la <b>Traduction des groupes de champs</b>','To translate field labels from the <b>Translation Management</b> dashboard, finish the <b>Multilingual Setup</b> and save your field group settings.'=>'Pour traduire les libellés des champs depuis le tableau de bord de la <b>Gestion des traductions</b>, terminez la <b>Configuration multilingue</b> et enregistrez les réglages de votre groupe de champs.','OK'=>'OK','Translate Field Labels'=>'Traduire les libellés des champs','To translate field labels, use the <b>Translation Management</b> dashboard.'=>'Pour traduire les libellés des champs, utilisez le tableau de bord de la <b>Gestion des traductions</b>.','Translate in <b>Translation Management</b>'=>'Traduire dans la <b>Gestion des traductions</b>','Don’t want to translate field labels? %1$sLearn how to disable field label translation%2$s'=>'Vous ne voulez pas traduire les libellés des champs ? %1$sDécouvrez comment désactiver la traduction des libellés de champs%2$s','Field Labels Partly Translated'=>'Libellés de champs partiellement traduits','Some field labels in this group are still untranslated. To finish translating them, go to the <b>Translation Management</b> dashboard.'=>'Certains libellés de champs de ce groupe ne sont pas encore traduits. Pour finir de les traduire, allez dans le tableau de bord de la <b>Gestion des traductions</b>.','Fields Labels Already Translated'=>'Libellés de champs déjà traduits','You already translated all field labels in this group. To update any translations, go to the <b>Translation Management</b> dashboard.'=>'Vous avez déjà traduit tous les libellés de champs de ce groupe. Pour mettre à jour les traductions, allez dans le tableau de bord de la <b>Gestion des traductions</b>.','Go to <b>Translation Management</b>'=>'Aller à la <b>Gestion des traductions</b>','Select a translation option for this field group'=>'Sélectionnez une option de traduction pour ce groupe de champs','Visitors everywhere see the same pages, in their own language. Text is translated; layout and settings stay identical.'=>'Les visiteurs voient partout les mêmes pages, dans leur propre langue. Le texte est traduit ; la mise en page et les réglages restent identiques.','You translate in the WPML <b>Translation Editor</b>. This works with automatic translation and <b>Translate Everything</b>.'=>'Vous traduisez dans l’<b>Éditeur de traduction</b> de WPML. Cela fonctionne avec la traduction automatique et <b>Tout traduire</b>.','Every language’s pages are written and maintained on their own. Fields start as a copy of the original, then go their own way.'=>'Les pages de chaque langue sont rédigées et gérées indépendamment. Les champs commencent par une copie de l’original, puis évoluent séparément.','You edit each language in the WordPress editor. WPML does not sync them afterwards, and automatic translation does not apply.'=>'Vous modifiez chaque langue dans l’éditeur WordPress. WPML ne les synchronise pas par la suite, et la traduction automatique ne s’applique pas.','If you are migrating a site, your existing field groups will use the Expert setup. This allows you to manually choose the translation option for each field in the group.'=>'Si vous migrez un site, vos groupes de champs existants utiliseront la configuration Expert. Cela vous permet de choisir manuellement l’option de traduction pour chaque champ du groupe.','This option is %1$snot recommended%2$s for new field groups.'=>'Cette option n’est %1$spas recommandée%2$s pour les nouveaux groupes de champs.','Expert setup documentation'=>'Documentation de la configuration Expert','Choose'=>'Choisir','recommended for this site'=>'recommandé pour ce site','Change option'=>'Changer d’option','A Much Simpler Way to Translate Your ACF Sites'=>'Une façon bien plus simple de traduire vos sites ACF','This new release of ACFML allows you to configure multilingual sites in one-click, instead of many complex settings. Choose how to setup the translation for the fields.'=>'Cette nouvelle version d’ACFML vous permet de configurer des sites multilingues en un clic, au lieu de nombreux réglages complexes. Choisissez comment configurer la traduction des champs.','Go to WPML Settings'=>'Aller aux paramètres de WPML','Need help choosing?'=>'Besoin d’aide pour choisir ?','Documentation'=>'Documentation','How to translate field labels »'=>'Comment traduire les libellés de champs »','This setup translates field values.'=>'Cette configuration traduit les valeurs des champs.','Translate field labels and dropdown choice labels separately. Find them under ACF Field Group in the <b>Translation Dashboard</b>.'=>'Traduisez séparément les libellés de champs et les libellés de choix des listes déroulantes. Retrouvez-les sous Groupe de champs ACF dans le <b>Tableau de bord de traduction</b>.','Review these translation setting changes'=>'Réviser ces modifications de réglages de traduction','Saving this field group makes these changes:'=>'L’enregistrement de ce groupe de champs effectue ces modifications :','%1$s: from “%2$s” to “%3$s”'=>'%1$s : de « %2$s » à « %3$s »','Switching to the field-by-field setup keeps every field\'s current setting. From here you set each field yourself.'=>'Passer à la configuration champ par champ conserve le réglage actuel de chaque champ. À partir d’ici, vous réglez chaque champ vous-même.','New translations use the new settings automatically.'=>'Les nouvelles traductions utilisent automatiquement les nouveaux réglages.','Not set'=>'Non défini','No posts with translations use this field group yet, so nothing has to be sent again.'=>'Aucune publication avec des traductions n’utilise encore ce groupe de champs, rien n’a donc besoin d’être renvoyé.','No terms with translations use this field group yet, so nothing has to be sent again.'=>'Aucun terme avec des traductions n’utilise encore ce groupe de champs, rien n’a donc besoin d’être renvoyé.','No posts or terms with translations use this field group yet, so nothing has to be sent again.'=>'Aucune publication ni aucun terme avec des traductions n’utilise encore ce groupe de champs, rien n’a donc besoin d’être renvoyé.','Only apply to new translations'=>'Appliquer uniquement aux nouvelles traductions','Checking how much content this affects...'=>'Vérification de la quantité de contenu affecté...','Save changes'=>'Enregistrer les modifications','No, go back'=>'Non, revenir en arrière','Updating them sends them for translation again, which may use translation words.'=>'Leur mise à jour les envoie à nouveau en traduction, ce qui peut consommer des mots de traduction.','Updating them marks their translations as needing an update. WPML does not send them for translation. You can send them from the Translation Dashboard.'=>'Les mettre à jour marque leurs traductions comme nécessitant une mise à jour. WPML ne les envoie pas en traduction. Vous pouvez les envoyer depuis le Tableau de bord de traduction.','Switching the setup applies the recommended value to the %d field in this group.'=>'Changer la configuration applique la valeur recommandée au %d champ de ce groupe.' . "\0" . 'Changer la configuration applique la valeur recommandée aux %d champs de ce groupe.','%d post already has translations that used the old settings.'=>'%d publication possède déjà des traductions qui utilisaient les anciens réglages.' . "\0" . '%d publications possèdent déjà des traductions qui utilisaient les anciens réglages.','%d term already has translations that used the old settings.'=>'%d terme possède déjà des traductions qui utilisaient les anciens réglages.' . "\0" . '%d termes possèdent déjà des traductions qui utilisaient les anciens réglages.','%d post uses this field group.'=>'%d publication utilise ce groupe de champs.' . "\0" . '%d publications utilisent ce groupe de champs.','%d post is translated by hand, so WPML does not send it for translation.'=>'%d publication est traduite manuellement, WPML ne l\'envoie donc pas en traduction.' . "\0" . '%d publications sont traduites manuellement, WPML ne les envoie donc pas en traduction.','Also update the %d existing post'=>'Mettre également à jour la %d publication existante' . "\0" . 'Mettre également à jour les %d publications existantes','Also update the %d existing term'=>'Mettre également à jour le %d terme existant' . "\0" . 'Mettre également à jour les %d termes existants','Also update the %1$d existing posts and %2$d terms'=>'Mettre également à jour les %1$d publications existantes et les %2$d termes','Also update the %1$d existing post and %2$d terms'=>'Mettre également à jour la %1$d publication existante et les %2$d termes','Also update the %1$d existing posts and %2$d term'=>'Mettre également à jour les %1$d publications existantes et le %2$d terme','Also update the %1$d existing post and %2$d term'=>'Mettre également à jour la %1$d publication existante et le %2$d terme','This field group is shown on an Options page.'=>'Ce groupe de champs est affiché sur une page d’options.','That is usually site-wide content like your header, footer, or global blocks.'=>'Il s’agit généralement de contenu s’appliquant à l’ensemble du site, comme votre en-tête, votre pied de page ou vos blocs globaux.','To translate that content, use the %1$sWPML Translation Dashboard%2$s.'=>'Pour traduire ce contenu, utilisez le %1$sTableau de bord de traduction de WPML%2$s.','The options below still decide how each field behaves: translated, copied to every language, or kept separately per language.'=>'Les options ci-dessous déterminent toujours le comportement de chaque champ : traduit, copié dans chaque langue ou conservé séparément par langue.','This field group also appears on an Options page.'=>'Ce groupe de champs apparaît également sur une page d’options.','That content is translated in the %1$sWPML Translation Dashboard%2$s, and the option you choose here decides how each of its fields behaves.'=>'Ce contenu est traduit dans le %1$sTableau de bord de traduction de WPML%2$s, et l\'option que vous choisissez ici détermine le comportement de chacun de ses champs.','Post Type Translation'=>'Traduction des types de publication','Labels Translation'=>'Traduction des libellés','Taxonomy Translation'=>'Traduction de la taxonomie','Finish the ACF <b>Multilingual Setup</b>'=>'Terminer la <b>configuration multilingue</b> d’ACF','Before you can start translating, you need to edit each ACF Field Group to set a translation option for the fields inside it.'=>'Avant de pouvoir commencer la traduction, vous devez modifier chaque groupe de champs ACF pour définir une préférence de traduction pour les champs qu’il contient.','Read more about %1$show to translate your ACF custom fields%2$s'=>'En savoir plus sur %1$scomment traduire vos champs personnalisés ACF%2$s','%1$sSet translation options%2$s'=>'%1$sDéfinir les options de traduction%2$s','Let\'s Start Translating!'=>'Commençons la traduction !','Edit each Field Group to select a translation option for the fields inside it. If you don\'t set a translation option, you will not be able to translate your fields.'=>'Modifiez chaque groupe de champs pour sélectionner une préférence de traduction pour les champs qu’il contient. Si vous ne définissez pas de préférence de traduction, vous ne pourrez pas traduire vos champs.','A field in "%s" has the same name as a field in another field group. WPML stores translation preferences by field name, so two fields that share a name cannot be set differently.'=>'Un champ dans « %s » porte le même nom qu’un champ d’un autre groupe de champs. WPML stocke les préférences de traduction par nom de champ, de sorte que deux champs partageant un nom ne peuvent pas être configurés différemment.','Some fields in "%s" have the same name as fields in other field groups. WPML stores translation preferences by field name, so fields that share a name cannot be set differently.'=>'Certains champs dans « %s » portent le même nom que des champs d’autres groupes de champs. WPML stocke les préférences de traduction par nom de champ, de sorte que les champs partageant un nom ne peuvent pas être configurés différemment.','What you set here may not be what your visitors get'=>'Ce que vous configurez ici peut ne pas correspondre à ce que vos visiteurs voient','The field %1$s also exists in "%2$s". Rename this field to give it a translation setting of its own.'=>'Le champ %1$s existe également dans « %2$s ». Renommez ce champ pour lui donner son propre paramètre de traduction.','See both fields'=>'Voir les deux champs','Go to Media Translation settings'=>'Accéder aux paramètres de Traduction des médias','This content has ACF image, gallery, or file fields, but the alt text, caption, and title of their media will not be sent for translation. To include them, turn on "Translate Media Library texts when translating content" in WPML Media Translation settings.'=>'Ce contenu comporte des champs ACF d’image, de galerie ou de fichier, mais le texte alternatif, la légende et le titre de leurs médias ne seront pas envoyés pour traduction. Pour les inclure, activez « Traduire les textes de la médiathèque lors de la traduction du contenu » dans les paramètres de WPML Media Translation.','Media texts are not being translated'=>'Les textes des médias ne sont pas traduits','%1$sGo to Media Translation settings%2$s'=>'%1$sAccéder aux paramètres de Traduction des médias%2$s','Translate this Options page from the <b>Translation Dashboard</b>'=>'Traduisez cette page d’options depuis le <b>Tableau de bord de traduction</b>','You no longer need to switch the admin language to translate options manually. Translate all your options from the %1$sTranslation Dashboard%2$s.'=>'Vous n’avez plus besoin de changer la langue de l’administration pour traduire les options manuellement. Traduisez toutes vos options depuis le %1$sTableau de bord de traduction%2$s.','Go to the Translation Dashboard'=>'Accéder au Tableau de bord de traduction','To change a finished translation, go to %1$sTranslation Jobs%2$s and click on the Edit Translation icon.'=>'Pour modifier une traduction terminée, allez dans %1$sTravaux de traduction%2$s et cliquez sur l’icône Modifier la traduction.','Go to Translation Jobs'=>'Aller aux travaux de traduction','WPML blocked this save to prevent data loss. The form sent about %1$s fields, but the PHP max_input_vars limit on this server (%2$s) let fewer through. Saving now would permanently delete the fields that did not arrive, including repeater rows. Nothing was saved. Ask your host to raise max_input_vars above %1$s and save again.'=>'WPML a bloqué cet enregistrement pour éviter toute perte de données. Le formulaire a envoyé environ %1$s champs, mais la limite PHP max_input_vars de ce serveur en a laissé passer moins (%2$s). Enregistrer maintenant supprimerait définitivement les champs qui ne sont pas arrivés, y compris les lignes du répéteur. Rien n’a été enregistré. Demandez à votre hébergeur d’augmenter max_input_vars au-delà de %1$s et enregistrez à nouveau.','Save blocked to prevent data loss'=>'Enregistrement bloqué pour éviter la perte de données','You need to %1$stranslate this post manually%2$s because the field groups attached to it use different translation options:'=>'Vous devez %1$straduire cette publication manuellement%2$s car les groupes de champs qui lui sont rattachés utilisent des options de traduction différentes :','and %d more.'=>'et %d de plus.','Show all field groups'=>'Afficher tous les groupes de champs','and %d more'=>'et %d de plus','You need to translate this post manually because the field groups attached to it use different translation options: %s.'=>'Vous devez traduire cette publication manuellement car les groupes de champs qui lui sont rattachés utilisent des options de traduction différentes : %s.','Edit %s'=>'Modifier %s','Go to documentation'=>'Accéder à la documentation','This field value is copied from the default language and will be kept in sync across languages.'=>'La valeur de ce champ est copiée de la langue par défaut et sera maintenue synchronisée entre les langues.','Synchronise translations'=>'Synchroniser les traductions','Keep repeater and flexible sub-fields in the same order as the default language.'=>'Maintenir les sous-champs du répéteur et du contenu flexible dans le même ordre que la langue par défaut.','ACFML Synchronise translations'=>'ACFML Synchroniser les traductions','Translate ACF Local JSON and PHP-Registered Fields'=>'Traduire les champs ACF enregistrés via PHP et JSON local','ACF allows you to %1$sregister fields via PHP%2$s or %3$ssave field settings as JSON files%4$s. You can also save post types, taxonomies, or options pages settings to JSON files.'=>'ACF vous permet d’%1$senregistrer des champs via PHP%2$s ou d’%3$senregistrer les paramètres des champs sous forme de fichiers JSON%4$s. Vous pouvez également enregistrer les paramètres des types de publication, des taxonomies ou des pages d’options dans des fichiers JSON.','Configure how ACF Multilingual handles translations for these items.'=>'Configurez la manière dont ACF Multilingual gère les traductions pour ces éléments.','Sync <b>Translation Preferences</b> for Local Fields'=>'Synchroniser les <b>préférences de traduction</b> pour les champs locaux','Don’t sync translation preferences'=>'Ne pas synchroniser les préférences de traduction','Sync once now'=>'Synchroniser une fois maintenant','Sync on every request (may affect performance)'=>'Synchroniser à chaque requête (peut affecter les performances)','Register Labels for Translation'=>'Enregistrer les libellés pour la traduction','Scans post types, taxonomies, options pages, and field groups stored in the "acf-json" directory, then registers their labels with WPML so you can translate them.'=>'Analyse les types de publication, les taxonomies, les pages d’options et les groupes de champs stockés dans le répertoire « acf-json », puis enregistre leurs libellés auprès de WPML afin que vous puissiez les traduire.','Don’t register labels'=>'Ne pas enregistrer les libellés','Register labels now'=>'Enregistrer les libellés maintenant','Apply'=>'Appliquer','The synchronization of translation preferences is disabled.'=>'La synchronisation des préférences de traduction est désactivée.','Translation preferences synchronized.'=>'Préférences de traduction synchronisées.','The synchronization of translation preferences is enabled.'=>'La synchronisation des préférences de traduction est activée.','%s group'=>'%s groupe' . "\0" . '%s groupes','%s post type'=>'%s type de publication' . "\0" . '%s types de publication','%s taxonomy'=>'%s taxonomie' . "\0" . '%s taxonomies','%s options page'=>'%s page d’options' . "\0" . '%s pages d’options','No local field groups, post types, taxonomies, or Options pages were found.'=>'Aucun groupe de champs local, type de publication, taxonomie ou page d’options n’a été trouvé.','Used between elements of a two elements list and '=>' et ','Used before the last element of a three or more elements list, and '=>', et ','Successfully registered labels for %s.'=>'Libellés enregistrés avec succès pour %s.','%1$sChange translation settings%2$s'=>'%1$sModifier les paramètres de traduction%2$s','%1$sTranslate labels%2$s'=>'%1$sTraduire les libellés%2$s','Not translatable'=>'Non traduisible','Translatable'=>'Traduisible','only show translated items'=>'afficher uniquement les éléments traduits','use translation if available or fallback to default language'=>'utiliser la traduction si elle est disponible ou se rabattre sur la langue par défaut','This content must be translated manually due to the translation option you selected for the "%1$s" field group.'=>'Ce contenu doit être traduit manuellement en raison de l’option de traduction que vous avez sélectionnée pour le groupe de champs « %1$s ».']];